class LmdbNativeMarginalAggregateStateTest {
	@Test
	void sharedDistinctArgumentUpdatesEveryConsumerExactlyOnce() {
		NativeLmdbQuerySource source = source();
		RowState row = row(source);
		AggregateSpec[] specs = {
				AggregateSpec.slot("n", 0, true, AggKind.COUNT),
				AggregateSpec.slot("sum", 0, true, AggKind.SUM),
				AggregateSpec.slot("avg", 0, true, AggKind.AVG),
				AggregateSpec.star("all") };
		AggregateDistinctChannels channels = AggregateDistinctChannels.allHash(specs);
		assertEquals(1, channels.channelCount());
		// Exercise both immediate numeric folding and deferred HASH membership folding.
		for (boolean deferred : new boolean[] { false, true }) {
			AggContext context = new AggContext(source, true, true, deferred);
			try {
				AggState state = new AggState(specs, 4, context, channels);
				for (long id : new long[] { 1L, 1L, 2L, 0L, UNKNOWN }) {
					row.slots[0] = id;
					state.addProjected(row, 100L, new int[] { 0, 1, 2 }, new int[] { 0 });
				}
				state.finishDistinctValueAggregate(1);
				state.finishDistinctValueAggregate(2);
				assertEquals(2L, state.count(0));
				assertEquals(BigInteger.valueOf(3L), state.sums[1].integerValue());
				assertEquals(BigInteger.valueOf(3L), state.sums[2].integerValue());
				assertEquals(2L, state.avgCounts[2]);
				assertEquals(0L, state.count(3), "unrelated wildcard channels are not updated by a marginal");
			} finally {
				context.close();
			}
		}
	}

	@Test
	void weightedArgumentsIgnoreNullAndDoNotMultiplyDistinctInputs() {
		NativeLmdbQuerySource source = source();
		RowState row = row(source);
		AggregateSpec[] specs = { AggregateSpec.slot("sum", 0, false, AggKind.SUM),
				AggregateSpec.slot("avg", 0, false, AggKind.AVG), AggregateSpec.star("rows") };
		AggContext context = new AggContext(source, true, true);
		try {
			AggState state = new AggState(specs, 4, context, AggregateDistinctChannels.allHash(specs));
			row.slots[0] = 2L;
			state.addProjected(row, 7L, new int[] { 0, 1 }, new int[0]);
			row.slots[0] = 0L;
			state.addProjected(row, 999L, new int[] { 0, 1 }, new int[0]);
			assertEquals(BigInteger.valueOf(14L), state.sums[0].integerValue());
			assertEquals(BigInteger.valueOf(14L), state.sums[1].integerValue());
			assertEquals(7L, state.avgCounts[1]);
			assertEquals(0L, state.count(2));
			assertThrows(IllegalArgumentException.class,
					() -> state.addProjected(row, 0L, new int[0], new int[0]));
		} finally {
			context.close();
		}
	}

	@Test
	void scalarFloatingFoldRetainsTheExplicitEncounterSequenceThroughMaterialization() {
		for (boolean distinct : new boolean[] { false, true }) {
			assertFloatingFold(distinct, new long[] { 1L, 2L, 3L }, 1.0d);
		}
	}

	@Test
	void scalarFloatingDistinctKeepsFirstEncounterRatherThanHashIterationOrder() {
		assertFloatingFold(false, new long[] { 1L, 1L, 2L, 2L, 3L, 3L }, 2.0d);
		assertFloatingFold(true, new long[] { 1L, 1L, 2L, 2L, 3L, 3L }, 1.0d);
	}

	@Test
	void deferredFloatingDistinctSignalsFallbackAtTheActualResultConsumer() {
		NativeLmdbQuerySource source = floatingSource();
		RowState row = row(source);
		AggregateSpec[] specs = floatingSpecs(true);
		AggContext context = new AggContext(source, true, true, true);
		try {
			AggState state = new AggState(specs, 4, context, AggregateDistinctChannels.allHash(specs));
			for (long id : new long[] { 1L, 2L, 3L, 1L }) {
				row.slots[0] = id;
				state.add(row);
			}
			EncounterOrderFallback fallback = assertThrows(EncounterOrderFallback.class,
					() -> materializeFloating(row, specs, state));
			assertEquals(EncounterOrderFallback.Reason.FLOATING_SUM_OR_AVG, fallback.reason);
		} finally {
			context.close();
		}
	}

	private static void assertFloatingFold(boolean distinct, long[] sequence, double expectedSum) {
		NativeLmdbQuerySource source = floatingSource();
		RowState row = row(source);
		AggregateSpec[] specs = floatingSpecs(distinct);
		AggContext context = new AggContext(source, true, false, false);
		try {
			AggState state = new AggState(specs, 4, context, AggregateDistinctChannels.allHash(specs));
			for (long id : sequence) {
				row.slots[0] = id;
				state.add(row);
			}
			BindingSet result = materializeFloating(row, specs, state);
			assertEquals(SimpleValueFactory.getInstance().createLiteral(expectedSum), result.getValue("sum"));
			assertEquals(SimpleValueFactory.getInstance().createLiteral(1.0d / 3.0d), result.getValue("avg"));
		} finally {
			context.close();
		}
	}

	private static BindingSet materializeFloating(RowState row, AggregateSpec[] specs, AggState state) {
		try (NativeGroupIteration owner = new NativeGroupIteration(row.source, SingletonPlan.INSTANCE, row.layout,
				new int[0], specs, true, row.base, null, null, false, null)) {
			return owner.toBindingSet(null, state, true);
		}
	}

	private static AggregateSpec[] floatingSpecs(boolean distinct) {
		return new AggregateSpec[] { AggregateSpec.slot("sum", 0, distinct, AggKind.SUM),
				AggregateSpec.slot("avg", 0, distinct, AggKind.AVG) };
	}

	/** Test-local dictionary codec only; these IDs never claim a physical source or probe capability. */
	private static NativeLmdbQuerySource floatingSource() {
		NativeLmdbQuerySource source = source();
		when(source.lazyValue(1L, ValuePosition.NONE))
				.thenReturn(SimpleValueFactory.getInstance().createLiteral(1.0e16d));
		when(source.lazyValue(2L, ValuePosition.NONE))
				.thenReturn(SimpleValueFactory.getInstance().createLiteral(-1.0e16d));
		when(source.lazyValue(3L, ValuePosition.NONE))
				.thenReturn(SimpleValueFactory.getInstance().createLiteral(1.0d));
		return source;
	}

	private static NativeLmdbQuerySource source() {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		when(source.idSpace()).thenReturn(source);
		when(source.lazyValue(anyLong(), eq(ValuePosition.NONE)))
				.thenAnswer(call -> AggContext.integerLiteral(call.getArgument(0)));
		return source;
	}

	private static RowState row(NativeLmdbQuerySource source) {
		LinkedHashMap<String, Integer> slots = new LinkedHashMap<>();
		slots.put("x", 0);
		NativeSlotLayout layout = new NativeSlotLayout(slots, null);
		layout.freeze(List.of("x"));
		return new RowState(source, layout, EmptyBindingSet.getInstance());
	}
}
